CREATE TRIGGER channels_fts_insert AFTER INSERT ON channels BEGIN
  INSERT INTO channels_fts(rowid, name, display_name)
    VALUES (new.id, new.name, new.display_name);
END;

CREATE TRIGGER channels_fts_delete AFTER DELETE ON channels BEGIN
  INSERT INTO channels_fts(channels_fts, rowid, name, display_name)
    VALUES ('delete', old.id, old.name, old.display_name);
END;

CREATE TRIGGER channels_fts_update AFTER UPDATE OF name, display_name ON channels
  WHEN old.name IS NOT new.name OR old.display_name IS NOT new.display_name
BEGIN
  INSERT INTO channels_fts(channels_fts, rowid, name, display_name)
    VALUES ('delete', old.id, old.name, old.display_name);
  INSERT INTO channels_fts(rowid, name, display_name)
    VALUES (new.id, new.name, new.display_name);
END;

CREATE TRIGGER movies_fts_insert AFTER INSERT ON movies BEGIN
  INSERT INTO movies_fts(rowid, name) VALUES (new.id, new.name);
END;

CREATE TRIGGER movies_fts_delete AFTER DELETE ON movies BEGIN
  INSERT INTO movies_fts(movies_fts, rowid, name)
    VALUES ('delete', old.id, old.name);
END;

CREATE TRIGGER movies_fts_update AFTER UPDATE OF name ON movies
  WHEN old.name IS NOT new.name
BEGIN
  INSERT INTO movies_fts(movies_fts, rowid, name)
    VALUES ('delete', old.id, old.name);
  INSERT INTO movies_fts(rowid, name) VALUES (new.id, new.name);
END;

